const spreadsheetId = $env['SPREADSHEET_ID'];
const range = 'Doctors!A2:D';

const response = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'GET',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + range,
  }
);

if (!response.values || response.values.length === 0) {
  return 'No doctors are currently listed in the system.';
}

// Columns: A=DoctorName, B=Specialty, C=Availability, D=ConsultationFee
const doctors = response.values.map(row => ({
  DoctorName: row[0] || '',
  Specialty: row[1] || '',
  Availability: row[2] || '',
  ConsultationFee: row[3] || '',
}));

return JSON.stringify(doctors);

// Input: { "doctorName": "...", "date": "YYYY-MM-DD", "time": "HH:MM" }
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { doctorName, date, time } = params;

const spreadsheetId = $env['SPREADSHEET_ID'];
const range = 'Appointments!A2:G';

const response = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'GET',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + range,
  }
);

// ── LOGIC TRAP ──
// An empty (or absent) values array means no appointments exist at all → slot is available.
// A non-empty filtered conflicts array means the slot is already taken.
if (!response.values || response.values.length === 0) {
  return JSON.stringify({ available: true, message: 'The requested slot is available.' });
}

// Columns: A=PatientName, B=Phone, C=DoctorName, D=Date, E=Time, F=Status, G=CalendarEventId
const conflicts = response.values.filter(row => {
  const rowDoctor = (row[2] || '').trim().toLowerCase();
  const rowDate   = (row[3] || '').trim();
  const rowTime   = (row[4] || '').trim();
  const rowStatus = (row[5] || '').trim().toLowerCase();
  return (
    rowDoctor === doctorName.trim().toLowerCase() &&
    rowDate   === date.trim() &&
    rowTime   === time.trim() &&
    rowStatus !== 'cancelled'
  );
});

if (conflicts.length === 0) {
  return JSON.stringify({ available: true, message: 'The requested slot is available.' });
}

return JSON.stringify({
  available: false,
  message: 'The requested slot is already booked.',
  conflicts: conflicts.map(row => ({
    patientName: row[0] || '',
    phone:       row[1] || '',
    status:      row[5] || '',
  })),
});

// Input: { "patientName": "...", "phone": "...", "doctorName": "...", "date": "YYYY-MM-DD", "time": "HH:MM" }
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { patientName, phone, doctorName, date, time } = params;

const spreadsheetId = $env['SPREADSHEET_ID'];
const range = 'Appointments!A:G';

// Append a new row: PatientName | Phone | DoctorName | Date | Time | Status | CalendarEventId (empty placeholder)
const appendResponse = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'POST',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + encodeURIComponent(range) + ':append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS',
    body: {
      values: [[patientName, phone, doctorName, date, time, 'Booked', '']],
    },
  }
);

return JSON.stringify({
  success: true,
  message: 'Appointment booked successfully.',
  updatedRange: appendResponse.updates ? appendResponse.updates.updatedRange : '',
});

// Input: { "patientName": "...", "doctorName": "...", "date": "YYYY-MM-DD", "time": "HH:MM",
//          "timezoneOffset": "+HH:MM" (optional, defaults to env CLINIC_TIMEZONE_OFFSET or "+00:00"),
//          "summary": "...", "description": "..." }
// Dates are constructed as ISO 8601 with explicit timezone offset to avoid ambiguous local-time parsing.
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { patientName, doctorName, date, time, summary, description } = params;
const tzOffset = params.timezoneOffset || $env['CLINIC_TIMEZONE_OFFSET'] || '+00:00';

const calendarId = $env['GOOGLE_CALENDAR_ID'] || 'primary';

// Build RFC3339 start/end with explicit timezone offset (avoids local-time ambiguity)
const startDateTimeStr = date + 'T' + time + ':00' + tzOffset;
const startMs = new Date(startDateTimeStr).getTime();
if (isNaN(startMs)) {
  return JSON.stringify({ success: false, message: 'Invalid date or time format. Use YYYY-MM-DD and HH:MM.' });
}
const endMs = startMs + 30 * 60 * 1000;

function toRFC3339(ms, offset) {
  const d = new Date(ms);
  const pad = n => String(n).padStart(2, '0');
  const sign = offset.startsWith('-') ? -1 : 1;
  const parts = offset.replace('+', '').replace('-', '').split(':');
  const offsetMinutes = sign * (parseInt(parts[0], 10) * 60 + parseInt(parts[1] || '0', 10));
  const localMs = ms + offsetMinutes * 60000;
  const ld = new Date(localMs);
  return ld.getUTCFullYear() + '-' + pad(ld.getUTCMonth() + 1) + '-' + pad(ld.getUTCDate()) +
         'T' + pad(ld.getUTCHours()) + ':' + pad(ld.getUTCMinutes()) + ':' + pad(ld.getUTCSeconds()) +
         offset;
}

const startRFC = toRFC3339(startMs, tzOffset);
const endRFC   = toRFC3339(endMs,   tzOffset);

const event = {
  summary:     summary || ('Appointment: ' + patientName + ' with Dr. ' + doctorName),
  description: description || ('Patient: ' + patientName + ' | Doctor: ' + doctorName),
  start:  { dateTime: startRFC },
  end:    { dateTime: endRFC },
};

const createdEvent = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleCalendarOAuth2Api',
  {
    method: 'POST',
    url: 'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(calendarId) + '/events',
    body: event,
  }
);

return JSON.stringify({
  success: true,
  calendarEventId: createdEvent.id,
  htmlLink: createdEvent.htmlLink || '',
  message: 'Calendar event created. CalendarEventId: ' + createdEvent.id,
});

// Input: { "patientName": "...", "phone": "...", "doctorName": "...", "date": "YYYY-MM-DD",
//          "time": "HH:MM", "calendarEventId": "..." }
// Persists the CalendarEventId returned by Add to Google Calendar Tool into the Appointments sheet
// column G so that reschedule and cancel operations can retrieve it later.
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { patientName, phone, doctorName, date, time, calendarEventId } = params;

if (!calendarEventId) {
  return JSON.stringify({ success: false, message: 'calendarEventId is required.' });
}

const spreadsheetId = $env['SPREADSHEET_ID'];
const readRange = 'Appointments!A2:G';

// Read the sheet to locate the matching row
const readResponse = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'GET',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + readRange,
  }
);

if (!readResponse.values || readResponse.values.length === 0) {
  return JSON.stringify({ success: false, message: 'No appointments found in the sheet.' });
}

// Columns: A=PatientName, B=Phone, C=DoctorName, D=Date, E=Time, F=Status, G=CalendarEventId
// Rows are data rows starting at sheet row 2 (index 0 in the values array = row 2).
let targetRowIndex = -1;
for (let i = 0; i < readResponse.values.length; i++) {
  const row = readResponse.values[i];
  const rowPatient = (row[0] || '').trim().toLowerCase();
  const rowPhone   = (row[1] || '').trim();
  const rowDoctor  = (row[2] || '').trim().toLowerCase();
  const rowDate    = (row[3] || '').trim();
  const rowTime    = (row[4] || '').trim();
  const rowStatus  = (row[5] || '').trim().toLowerCase();
  if (
    rowPatient === patientName.trim().toLowerCase() &&
    rowPhone   === phone.trim() &&
    rowDoctor  === doctorName.trim().toLowerCase() &&
    rowDate    === date.trim() &&
    rowTime    === time.trim() &&
    rowStatus  !== 'cancelled'
  ) {
    targetRowIndex = i;
    break;
  }
}

if (targetRowIndex === -1) {
  return JSON.stringify({ success: false, message: 'Matching appointment row not found.' });
}

// Sheet row number = targetRowIndex + 2 (header occupies row 1, data starts at row 2)
const sheetRowNumber = targetRowIndex + 2;
const updateRange = 'Appointments!G' + sheetRowNumber;

await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'PUT',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + encodeURIComponent(updateRange) + '?valueInputOption=USER_ENTERED',
    body: {
      range: updateRange,
      majorDimension: 'ROWS',
      values: [[calendarEventId]],
    },
  }
);

return JSON.stringify({
  success: true,
  message: 'CalendarEventId saved to Appointments sheet at row ' + sheetRowNumber + '.',
  sheetRow: sheetRowNumber,
});

// Input: { "phone": "..." } or { "patientName": "..." } or { "doctorName": "...", "date": "YYYY-MM-DD" }
// Returns all matching appointments including calendarEventId. Always call this before rescheduling
// or cancelling to obtain the calendarEventId needed for Google Calendar operations.
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { phone, patientName, doctorName, date } = params;

const spreadsheetId = $env['SPREADSHEET_ID'];
const range = 'Appointments!A2:G';

const response = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'GET',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + range,
  }
);

if (!response.values || response.values.length === 0) {
  return JSON.stringify({ appointments: [], message: 'No appointments found.' });
}

// Columns: A=PatientName, B=Phone, C=DoctorName, D=Date, E=Time, F=Status, G=CalendarEventId
const appointments = response.values
  .map((row, idx) => ({
    rowNumber:       idx + 2,
    patientName:     row[0] || '',
    phone:           row[1] || '',
    doctorName:      row[2] || '',
    date:            row[3] || '',
    time:            row[4] || '',
    status:          row[5] || '',
    calendarEventId: row[6] || '',
  }))
  .filter(appt => {
    if (phone       && appt.phone.trim()      !== phone.trim())      return false;
    if (patientName && appt.patientName.trim().toLowerCase() !== patientName.trim().toLowerCase()) return false;
    if (doctorName  && appt.doctorName.trim().toLowerCase()  !== doctorName.trim().toLowerCase())  return false;
    if (date        && appt.date.trim()       !== date.trim())       return false;
    return true;
  });

if (appointments.length === 0) {
  return JSON.stringify({ appointments: [], message: 'No matching appointments found.' });
}

return JSON.stringify({ appointments });

// Input: { "patientName": "...", "phone": "...", "doctorName": "...",
//          "currentDate": "YYYY-MM-DD", "currentTime": "HH:MM",
//          "newDate": "YYYY-MM-DD", "newTime": "HH:MM",
//          "calendarEventId": "..." }
// The caller MUST retrieve calendarEventId via view_appointments before calling this tool.
// If calendarEventId is absent, the Sheets record is updated but the response includes a clear
// message that the calendar entry was not updated.
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { patientName, phone, doctorName, currentDate, currentTime, newDate, newTime, calendarEventId } = params;

const spreadsheetId = $env['SPREADSHEET_ID'];
const readRange = 'Appointments!A2:G';

const readResponse = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'GET',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + readRange,
  }
);

if (!readResponse.values || readResponse.values.length === 0) {
  return JSON.stringify({ success: false, message: 'No appointments found in the sheet.' });
}

let targetRowIndex = -1;
for (let i = 0; i < readResponse.values.length; i++) {
  const row = readResponse.values[i];
  if (
    (row[0] || '').trim().toLowerCase() === patientName.trim().toLowerCase() &&
    (row[1] || '').trim()               === phone.trim() &&
    (row[2] || '').trim().toLowerCase() === doctorName.trim().toLowerCase() &&
    (row[3] || '').trim()               === currentDate.trim() &&
    (row[4] || '').trim()               === currentTime.trim() &&
    (row[5] || '').trim().toLowerCase() !== 'cancelled'
  ) {
    targetRowIndex = i;
    break;
  }
}

if (targetRowIndex === -1) {
  return JSON.stringify({ success: false, message: 'Matching active appointment not found.' });
}

const sheetRowNumber = targetRowIndex + 2;
// Update Date (col D), Time (col E), and Status (col F); CalendarEventId (col G) is preserved.
const updateRange = 'Appointments!D' + sheetRowNumber + ':F' + sheetRowNumber;

await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'PUT',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + encodeURIComponent(updateRange) + '?valueInputOption=USER_ENTERED',
    body: {
      range: updateRange,
      majorDimension: 'ROWS',
      values: [[newDate, newTime, 'Rescheduled']],
    },
  }
);

let calendarNote;
if (!calendarEventId) {
  calendarNote = ' Note: CalendarEventId was not provided so the Google Calendar entry was not updated. Please update it manually.';
} else {
  calendarNote = ' Use update_google_calendar with calendarEventId "' + calendarEventId + '" to update the calendar event.';
}

return JSON.stringify({
  success: true,
  message: 'Appointment rescheduled in Google Sheets to ' + newDate + ' at ' + newTime + '.' + calendarNote,
  sheetRow: sheetRowNumber,
});

// Input: { "calendarEventId": "...", "newDate": "YYYY-MM-DD", "newTime": "HH:MM",
//          "timezoneOffset": "+HH:MM" (optional),
//          "summary": "...", "description": "..." }
// calendarEventId is mandatory. If missing, the tool returns an error without making any API call.
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { calendarEventId, newDate, newTime, summary, description } = params;

if (!calendarEventId) {
  return JSON.stringify({
    success: false,
    message: 'calendarEventId is missing. Retrieve it from view_appointments first. The Google Calendar entry has not been updated.',
  });
}

const tzOffset = params.timezoneOffset || $env['CLINIC_TIMEZONE_OFFSET'] || '+00:00';
const calendarId = $env['GOOGLE_CALENDAR_ID'] || 'primary';

const startDateTimeStr = newDate + 'T' + newTime + ':00' + tzOffset;
const startMs = new Date(startDateTimeStr).getTime();
if (isNaN(startMs)) {
  return JSON.stringify({ success: false, message: 'Invalid date or time format. Use YYYY-MM-DD and HH:MM.' });
}
const endMs = startMs + 30 * 60 * 1000;

function toRFC3339(ms, offset) {
  const d = new Date(ms);
  const pad = n => String(n).padStart(2, '0');
  const sign = offset.startsWith('-') ? -1 : 1;
  const parts = offset.replace('+', '').replace('-', '').split(':');
  const offsetMinutes = sign * (parseInt(parts[0], 10) * 60 + parseInt(parts[1] || '0', 10));
  const localMs = ms + offsetMinutes * 60000;
  const ld = new Date(localMs);
  return ld.getUTCFullYear() + '-' + pad(ld.getUTCMonth() + 1) + '-' + pad(ld.getUTCDate()) +
         'T' + pad(ld.getUTCHours()) + ':' + pad(ld.getUTCMinutes()) + ':' + pad(ld.getUTCSeconds()) +
         offset;
}

const patchBody = {
  start: { dateTime: toRFC3339(startMs, tzOffset) },
  end:   { dateTime: toRFC3339(endMs,   tzOffset) },
};
if (summary)     patchBody.summary     = summary;
if (description) patchBody.description = description;

const updatedEvent = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleCalendarOAuth2Api',
  {
    method: 'PATCH',
    url: 'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(calendarId) + '/events/' + encodeURIComponent(calendarEventId),
    body: patchBody,
  }
);

return JSON.stringify({
  success: true,
  message: 'Google Calendar event updated successfully.',
  eventId: updatedEvent.id,
  htmlLink: updatedEvent.htmlLink || '',
});

// Input: { "patientName": "...", "phone": "...", "doctorName": "...",
//          "date": "YYYY-MM-DD", "time": "HH:MM", "calendarEventId": "..." }
// The caller MUST retrieve calendarEventId via view_appointments before calling this tool.
// If calendarEventId is absent, the Sheets record is still updated but the response includes a clear
// message that the calendar entry was not deleted.
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { patientName, phone, doctorName, date, time, calendarEventId } = params;

const spreadsheetId = $env['SPREADSHEET_ID'];
const readRange = 'Appointments!A2:G';

const readResponse = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'GET',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + readRange,
  }
);

if (!readResponse.values || readResponse.values.length === 0) {
  return JSON.stringify({ success: false, message: 'No appointments found in the sheet.' });
}

let targetRowIndex = -1;
for (let i = 0; i < readResponse.values.length; i++) {
  const row = readResponse.values[i];
  if (
    (row[0] || '').trim().toLowerCase() === patientName.trim().toLowerCase() &&
    (row[1] || '').trim()               === phone.trim() &&
    (row[2] || '').trim().toLowerCase() === doctorName.trim().toLowerCase() &&
    (row[3] || '').trim()               === date.trim() &&
    (row[4] || '').trim()               === time.trim() &&
    (row[5] || '').trim().toLowerCase() !== 'cancelled'
  ) {
    targetRowIndex = i;
    break;
  }
}

if (targetRowIndex === -1) {
  return JSON.stringify({ success: false, message: 'Matching active appointment not found.' });
}

const sheetRowNumber = targetRowIndex + 2;
const updateRange = 'Appointments!F' + sheetRowNumber;

await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleSheetsOAuth2Api',
  {
    method: 'PUT',
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + spreadsheetId + '/values/' + encodeURIComponent(updateRange) + '?valueInputOption=USER_ENTERED',
    body: {
      range: updateRange,
      majorDimension: 'ROWS',
      values: [['Cancelled']],
    },
  }
);

let calendarNote;
if (!calendarEventId) {
  calendarNote = ' Note: CalendarEventId was not provided so the Google Calendar entry was not deleted. Please remove it manually.';
} else {
  calendarNote = ' Use delete_google_calendar_event with calendarEventId "' + calendarEventId + '" to delete the calendar event.';
}

return JSON.stringify({
  success: true,
  message: 'Appointment marked as Cancelled in Google Sheets.' + calendarNote,
  sheetRow: sheetRowNumber,
});

// Input: { "calendarEventId": "..." }
// calendarEventId is mandatory. If missing, the tool returns an error without making any API call.
let params;
try {
  params = JSON.parse(query);
} catch (e) {
  return JSON.stringify({ success: false, message: 'Invalid JSON input: ' + e.message });
}
const { calendarEventId } = params;

if (!calendarEventId) {
  return JSON.stringify({
    success: false,
    message: 'calendarEventId is missing. Retrieve it from view_appointments first. The Google Calendar entry has not been deleted.',
  });
}

const calendarId = $env['GOOGLE_CALENDAR_ID'] || 'primary';

await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleCalendarOAuth2Api',
  {
    method: 'DELETE',
    url: 'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(calendarId) + '/events/' + encodeURIComponent(calendarEventId),
  }
);

return JSON.stringify({
  success: true,
  message: 'Google Calendar event deleted successfully. CalendarEventId: ' + calendarEventId,
});
